UPDATE companies SET description='GMS Industries was founded in 1989 in El Paso, Texas, as a family-owned packaging manufacturer. The business remains under the ownership of the Glidden family, now led by second-generation brothers Kris Glidden (CEO) and Cory Glidden (COO), who took over from their parents and continue to run day-to-day operations.

The company produces pressure-sensitive labels (including freezer- and cold-chain-rated adhesives in roll and sheet formats with variable data printing), printed instruction sheets, folding cartons, corrugated and laminate shipping boxes, rigid setup boxes, and printed paper bags. Manufacturing takes place across facilities in the United States and Mexico, with in-house graphic design and prepress based in El Paso. The operation also warehouses and distributes standard corrugated boxes alongside custom runs.

GMS serves food and beverage, consumer packaged goods, pharmaceutical and nutraceutical, cosmetics and beauty, home and hardware, and e-commerce and retail brands. A noted long-term client is Kwikset, cited in a CEO Magazine profile as a decades-long supply-chain partner. The firm also holds a GSA Schedule contract (47QSMS26D004X), making it eligible for federal and enterprise set-aside procurement.

The founders'' original premise — that a packaging vendor should feel like part of the customer''s team rather than a transactional supplier — still guides the company. The Glidden brothers emphasize direct owner involvement, quote-driven pricing instead of catalog rates, and relationships measured in decades; their longest client has been with the company since its 1989 start.', certifications=ARRAY['GSA Schedule 47QSMS26D004X']::text[], profile='{"capabilities": ["Pressure sensitive label printing (freezer/cold-chain adhesives, roll/sheet, variable data)", "Printed instruction sheets (inserts, manuals, booklets, pamphlets)", "Folding carton printing and finishing (litho, digital, foils, finishes)", "Corrugated and laminate shipping box manufacturing", "Rigid setup box manufacturing", "Printed paper bag manufacturing", "Custom packaging design and production", "In-house graphic design and prepress", "Warehouse distribution of standard corrugated boxes"], "industries": ["Food & Beverage", "Consumer Packaged Goods", "Pharmaceuticals & Nutraceuticals", "Cosmetics & Beauty", "Home & Hardware", "E-commerce & Retail", "Federal Government (GSA Schedule)"], "materials": ["Paper", "Corrugated board", "Laminate", "Pressure-sensitive label stock"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned \u2014 led by Kris Glidden (CEO) and Cory Glidden (COO), co-owners", "GSA-Certified \u2014 eligible for federal and enterprise set-asides", "Manufacturing in the U.S. and Mexico across multiple plants", "Quote-driven, never catalog-priced \u2014 every job specced to the product", "In-house graphic design and prepress out of El Paso, TX"], "facts_used": ["Founded 1989 -> db", "Family-owned, second-generation led by Kris and Cory Glidden -> /about", "Manufacturing in U.S. and Mexico -> /", "Product lines: pressure sensitive labels, instruction sheets, folding cartons, corrugated boxes, rigid boxes, printed bags -> /", "Industries served: Food & Beverage, CPG, Pharmaceuticals & Nutraceuticals, Cosmetics & Beauty, Home & Hardware, E-commerce & Retail -> /", "GSA Schedule 47QSMS26D004X -> /", "Kwikset cited as decades-long client -> /", "In-house graphic design in El Paso -> /services", "Warehouse distributor for standard corrugated boxes -> /services", "Quote-driven, no catalog MOQ -> /services", "Longest client relationship 37 years -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "A US manufacturer of instruction sheets, labels and the cartons they go in.", "founded_year": "1989", "employee_count": "", "cage_code": "", "min_order": "Varies by product, substrate, and print method; no fixed catalog MOQ", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='gms-industries-el-paso-ops' AND approved AND profile IS NULL;
UPDATE companies SET description='GOEX Apparel operates from Kansas City, Missouri, where it prints and ships finished garments. The company''s supply chain spans 2,700 miles: fabrics are produced in South Carolina from U.S. materials, then cut and sewn at its owned factory in Haiti before final decoration in Kansas City. No founding year or founders are disclosed in public materials.

GOEX manufactures custom-printed apparel and wholesale basics, including eco-triblend tees for retail and promotional markets. Its Haiti facility handles cut-and-sew assembly, while the Kansas City warehouse manages printing and fulfillment. The company emphasizes a transparent, Western Hemisphere supply chain and evaluates fabrics annually for sustainability, using OEKO-TEX ECO PASSPORT certified textiles and Fair Trade certified labels.

The company serves organizations seeking branded merchandise—teams, events, musical tours, and retail partners. Named clients include the Minnesota Historical Society, Black Hills Basecamp, Biomes Marine Biology Center, and Koraa. GOEX also opens wholesale accounts for retailers stocking ethically made blanks.

GOEX positions itself as a "People and Planet First" wholesale apparel company, created to counter supply chains that prioritize low cost over people. It pays Haitian workers 65 percent above the sector minimum, holds Fair Trade Federation verification, B Corp certification, and memberships in the Fair Labor Association, Social Enterprise Alliance, and Social Enterprise World Forum. The mission is to create fair-wage jobs that strengthen families and communities.', certifications=ARRAY['FAIR TRADE','OEKO-TEX','Fair Trade Federation Verification','B Corp Certified','Fair Labor Association','Social Enterprise Alliance','Social Enterprise World Forum','OEKO-TEX ECO PASSPORT']::text[], profile='{"capabilities": ["Custom printed apparel", "Wholesale apparel basics", "Cut and sew manufacturing", "Screen printing", "Sustainable fabric sourcing", "Fair trade certified manufacturing", "Retail-quality garment decoration", "Wholesale account management"], "industries": ["Apparel manufacturing", "Wholesale trade", "Custom merchandise", "Promotional products", "Event merchandise", "Music merchandise", "Retail apparel"], "materials": ["Eco-Triblend fabric", "US-sourced fabrics", "OEKO-TEX ECO PASSPORT certified fabrics", "Fair Trade certified labels and tags", "Sustainable components"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["2,700-mile supply chain (fabrics from South Carolina, cut/sew in Haiti, print/ship from Kansas City)", "Fair Trade Federation verified and B Corp certified", "Pays workers 65% above Haiti''s apparel sector minimum", "OEKO-TEX ECO PASSPORT certified fabrics", "USA fabrics cut and sewn in the Western Hemisphere"], "facts_used": ["Headquarters in Kansas City, Missouri -> db", "Factory in Haiti for cut and sew -> /", "Fabrics made in South Carolina from US materials -> /", "2,700-mile supply chain -> /", "Custom printed apparel and wholesale basics -> /", "Eco-Triblend tees offered -> /", "Fair Trade Federation verified ->