ype_evidence": "Goose Woodworking, LLC specializes in making custom, handmade furniture out of high-quality hardwoods", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Small business"]}'::jsonb, updated_at=now() WHERE slug='goose-woodworking-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Grain Designs operates from Fargo, North Dakota, where it was founded in 2013 by architectural designers who began building furniture in a two‑stall garage. The studio has since grown into a design‑and‑build workshop rooted at The Pines, a creative hub where craftsmanship and community intersect.

The company produces custom hardwood furniture for both commercial and residential clients, including reception desks, office desks, conference tables, live‑edge tables, dining tables, and podcast/media desks. Every piece is fabricated from solid hardwoods, finished to order, and delivered fully assembled; typical turnaround is as little as six weeks from design approval.

Grain Designs serves businesses across sectors such as financial services, media production, and corporate workspace design. Its portfolio includes projects for NorthStar Financial (conference tables, sit‑stand desks, shelving), You Betcha! (office desks, podcast table, container bar), and Enclave Companies’ flagship office (meeting tables, conference table, shelving). The firm reports having helped more than 100 businesses outfit their office spaces.

The founders started Grain Designs to create meaningful, well‑crafted furniture that lasts, rejecting imported mass‑production in favor of North Dakota‑made pieces built on client relationships. The company positions its custom work at or below the price of standard commercial office furniture, emphasizing on‑time, on‑budget delivery and a free design consultation that yields detailed drawings and finish options.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Solid hardwood fabrication", "Custom wood finishing", "Furniture assembly and delivery", "Project management for commercial build\u2011outs"], "industries": ["Commercial office", "Residential", "Financial services", "Media production", "Corporate workspace"], "materials": ["Solid hardwoods"], "equipment": [], "volume": "", "lead_time": "6 weeks for custom orders", "tolerances": "", "built_on": ["Custom hardwood desks and tables priced at or below commercial competitors", "Six\u2011week build and delivery timeline", "All furniture made in North Dakota with no imported mass\u2011produced components", "Free design consultation with custom drawings and finish options", "Over 100 commercial office projects completed"], "facts_used": ["Founded in 2013 in a two-stall garage in Fargo -> /", "Headquarters at The Pines in Fargo, North Dakota -> /", "Produces custom hardwood furniture (desks, tables, reception, conference, live-edge, dining, podcast/media) -> /", "Typical turnaround as little as 6 weeks -> /", "Serves commercial and residential clients; examples: NorthStar Financial, You Betcha!, Enclave Companies -> /", "Over 100 businesses helped with office spaces -> /", "No imported mass-produced furniture; North Dakota made -> /", "Free design consultation with custom quote, drawings, finish options -> /", "Company type: manufacturer of custom furniture -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Grain Designs offers custom designed hardwood desks and tables for the same price or less than commercial office furniture competitors.", "founded_year": "2013", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='grain-designs' AND approved AND profile IS NULL;
UPDATE companies SET description='Grand Forks Welding & Machine traces its roots to 1885, when a blacksmith shop called Grand Forks Foundry opened in Dakota Territory to repair riverboats. The business evolved over more than a century into the present-day operation in Grand Forks, North Dakota. No founders are named in the available records, and ownership structure is not disclosed.

The company provides custom fabrication, repair, machining, and drive-line services, supplemented by CNC plasma cutting and custom U-bolt manufacturing. It maintains an in-stock inventory of steel, stainless steel, aluminum, and plastics, and runs a fully stocked parts department supplying brands such as Neapco, Weasler, Waterscheid, and Dexter for driveline, PTO, and trailer components. Facility size, headcount, and annual volumes are not published.

The shop serves builders, manufacturers, and agricultural producers — sectors that have relied on its capabilities since the riverboat era. Concrete examples include fabricating new items, repairing existing designs, and supplying replacement parts to keep equipment running in construction, industrial, and farm settings.

The company emphasizes a reputation for high-quality work and responsive service, noting that its highly trained staff can design, build, or repair almost anything a customer requires. The original mission — keeping river traffic moving — expanded into a broader commitment to minimizing downtime for modern industrial and agricultural clients.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Fabrication & Repair", "Machining & Drive Line", "CNC Plasma Cutting", "Custom U-Bolt Manufacturing", "Parts Department"], "industries": ["Builders", "Manufacturers", "Agricultural producers"], "materials": ["Steel", "Stainless Steel", "Aluminum", "Plastics"], "equipment": ["CNC Plasma Cutting"], "volume": "", "lead_time": "Within 2 weeks for most projects", "tolerances": "", "built_on": ["Projects typically completed within two weeks", "Fully stocked parts department with Neapco, Weasler, Waterscheid, Dexter lines", "In-stock inventory of steel, stainless steel, aluminum, and plastics", "Highly trained staff capable of design, fabrication, and repair", "Heritage dating back to 1885 riverboat repair in Dakota Territory"], "facts_used": ["Founded 1885 as Grand Forks Foundry in Dakota Territory -> /", "Located in Grand Forks, North Dakota -> db", "Offers fabrication, repair, machining, drive line, CNC plasma cutting -> /", "Carries steel, stainless steel, aluminum, plastics in stock -> /", "Parts department with Neapco, Weasler, Waterscheid, Dexter trailer parts -> /", "Serves builders, manufacturers, agricultural producers -> /", "Projects fulfilled within 2 weeks or less -> db", "Highly trained staff for design, build, repair -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Grand Forks Welding''s Men of Steel will fabricate new items and repair and improve existing designs. Additionally, our fully stocked parts department eliminates your down time and builds up time.", "founded_year": "1885", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='grand-forks-welding-machine-co' AND approved AND profile IS NULL;
